window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fb77ed0e788ddb33"]={"versions": [{"id": "FIG-fb77ed0e788ddb33", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und oberen Schichten (CanIf User) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Generische obere Schicht / Anwender des CAN-Interface (z. B. PduR, CanTp, CanNm).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]:DLC Check (optional)</code>: Interne Prüfung der Data Length / des DLC in CanIf.\n</li><li><code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das konfigurierte obere Modul.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des Anwenders auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der DLC-Check.\n</li><li><code>CanIf</code> leitet den Empfang an den oberen Anwender über <code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code> weiter.\n</li><li>Der Anwender kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>&lt;User_RxIndication&gt;</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>&lt;User_RxIndication&gt;()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in den <code>CanIf User</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und DLC-Prüfung sind konfigurierbar.\n</li><li>Hinweis zur Schnittstellenparametrisierung: Parameter der User-Indikation variieren bei abweichenden Usern (exemplarisch erwähnt für CanTp).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-378b98780b692dce", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und oberen Schichten (CanIf User) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Generische obere Schicht / Anwender des CAN-Interface (z. B. PduR, CanTp, CanNm).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]:DLC Check (optional)</code>: Interne Prüfung der Data Length / des DLC in CanIf.\n</li><li><code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das konfigurierte obere Modul.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des Anwenders auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der DLC-Check.\n</li><li><code>CanIf</code> leitet den Empfang an den oberen Anwender über <code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code> weiter.\n</li><li>Der Anwender kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>&lt;User_RxIndication&gt;</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>&lt;User_RxIndication&gt;()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in den <code>CanIf User</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und DLC-Prüfung sind konfigurierbar.\n</li><li>Hinweis zur Schnittstellenparametrisierung: Parameter der User-Indikation variieren bei abweichenden Usern (exemplarisch erwähnt für CanTp).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-73705e281667570f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und oberen Schichten (CanIf User) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Generische obere Schicht / Anwender des CAN-Interface (z. B. PduR, CanTp, CanNm).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]: Data Length Check (optional)</code>: Interne Datenlängenprüfung (Data Length Check) in CanIf.\n</li><li><code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das konfigurierte obere Modul.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des Anwenders auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der Data Length Check.\n</li><li><code>CanIf</code> leitet den Empfang an den oberen Anwender über <code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code> weiter.\n</li><li>Der Anwender kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>&lt;User_RxIndication&gt;</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>&lt;User_RxIndication&gt;()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in den <code>CanIf User</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und Data Length Check sind konfigurierbar.\n</li><li>Hinweis zur Schnittstellenparametrisierung: Parameter der User-Indikation variieren bei abweichenden Usern (exemplarisch erwähnt für CanTp).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f7ea097f846ddc03", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und oberen Schichten (CanIf User) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Generische obere Schicht / Anwender des CAN-Interface (z. B. PduR, CanTp, CanNm).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]: Data Length Check (optional)</code>: Interne Datenlängenprüfung (Data Length Check) in CanIf.\n</li><li><code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das konfigurierte obere Modul.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des Anwenders auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der Data Length Check.\n</li><li><code>CanIf</code> leitet den Empfang an den oberen Anwender über <code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code> weiter.\n</li><li>Der Anwender kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>&lt;User_RxIndication&gt;</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>&lt;User_RxIndication&gt;()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in den <code>CanIf User</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und Data Length Check sind konfigurierbar.\n</li><li>Hinweis zur Schnittstellenparametrisierung: Parameter der User-Indikation variieren bei abweichenden Usern (exemplarisch erwähnt für CanTp).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3e4c75f2a398480c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und dem Large SDU Router (LSduR) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«module» LSduR</code>: Large SDU Router als übergeordnete Schichtkomponente.\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]: Data Length Check (optional)</code>: Interne Datenlängenprüfung (Data Length Check) in CanIf.\n</li><li><code>LSduR_CanIfRxIndication(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das Modul LSduR.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des LSduR auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der Data Length Check.\n</li><li><code>CanIf</code> leitet den Empfang an das Modul LSduR über <code>LSduR_CanIfRxIndication(PduIdType, const PduInfoType*)</code> weiter.\n</li><li><code>LSduR</code> kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>LSduR_CanIfRxIndication</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>LSduR_CanIfRxIndication()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in das Modul <code>LSduR</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und Data Length Check sind konfigurierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6b204f1857b902e8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und dem Large SDU Router (LSduR) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>«module» LSduR</code>: Large SDU Router als übergeordnete Schichtkomponente.\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]: Data Length Check (optional)</code>: Interne Datenlängenprüfung (Data Length Check) in CanIf.\n</li><li><code>LSduR_CanIfRxIndication(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das Modul LSduR.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des LSduR auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der Data Length Check.\n</li><li><code>CanIf</code> leitet den Empfang an das Modul LSduR über <code>LSduR_CanIfRxIndication(PduIdType, const PduInfoType*)</code> weiter.\n</li><li><code>LSduR</code> kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>LSduR_CanIfRxIndication</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>LSduR_CanIfRxIndication()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in das Modul <code>LSduR</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und Data Length Check sind konfigurierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-452fe907a1e23233", "releases": ["R21-11", "R22-11", "R23-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des interruptgetriebenen Empfangspfads (Receive Indication) im AUTOSAR-CAN-Stack. Das Diagramm zeigt das Zusammenspiel zwischen Hardwareschicht (CAN-Controller), Treiber- bzw. Abstraktionsschicht (Can, CanIf) und oberen Schichten (CanIf User) während der Interruptverarbeitung eines empfangenen CAN-Frames.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>CanIf User</code>: Generische obere Schicht / Anwender des CAN-Interface (z. B. PduR, CanTp, CanNm).\n</li><li><code>«module» CanIf</code>: AUTOSAR CAN Interface Modul.\n</li><li><code>«module» Can</code>: AUTOSAR CAN Driver Modul.\n</li><li><code>«Peripheral» CanController</code>: Hardware-CAN-Controller (Peripherie).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li><code>Receive Interrupt()</code>: Hardware-Interruptmeldung vom Controller an den CAN-Treiber sowie Rückkehr nach Beendigung.\n</li><li><code>Invalidation of hardware object()</code>: Sperren/Ungültig-Erklären des Hardware-Objekts im Controller durch den Treiber.\n</li><li><code>Copy received L-PDU into temporary buffer()</code>: Pufferkopieroperation aus dem Hardware-Objekt in einen Treiber-Puffer.\n</li><li><code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Übergabe der empfangenen L-PDU vom CAN-Treiber an das CAN-Interface.\n</li><li><code>Software filtering (optional) and L-PDU assignment</code>: Interne Filter- und Zuordnungsroutine in CanIf.\n</li><li><code>[CAN L-PDU ID was found]: Data Length Check (optional)</code>: Interne Datenlängenprüfung (Data Length Check) in CanIf.\n</li><li><code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code>: Callback-Indikation von CanIf an das konfigurierte obere Modul.\n</li><li><code>Copy Data()</code>: Datenkopierzugriff des Anwenders auf Treiber- bzw. Controller-Puffer.\n</li><li><code>Validation of hardware object()</code>: Revalidierung / Freigabe des Hardware-Objekts im Controller durch den Treiber nach Abschluss der Verarbeitung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Hardware-Controller löst via <code>Receive Interrupt()</code> die ISR im <code>Can</code>-Treiber aus.\n</li><li>Der Treiber invalidiert das Hardware-Empfangsobjekt über <code>Invalidation of hardware object()</code>.\n</li><li>Bedingter Ablauf (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Wenn eine Datennormalisierung erforderlich ist (<code>[Temp. buffer used = Data normalization necessary]</code>), kopiert der Treiber die L-PDU via <code>Copy received L-PDU into temporary buffer()</code> in einen temporären Puffer.\n</li><li>Ist keine Normalisierung nötig (<code>[Temp. buffer not used = Data normalization not necessary]</code>), entfällt dieser Schritt.\n</li></ul>\n</li><li>Der CAN-Treiber ruft <code>CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code> auf.\n</li><li><code>CanIf</code> führt intern optional Software-Filterung und L-PDU-Zuordnung durch. Wurde eine gültige L-PDU-ID gefunden, folgt optional der Data Length Check.\n</li><li><code>CanIf</code> leitet den Empfang an den oberen Anwender über <code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code> weiter.\n</li><li>Der Anwender kopiert die Nutzdaten (<code>alt Temporary buffer usage</code>):\n<ul class=\"fig-list\"><li>Bei Nutzung des temporären Puffers ruft <code>&lt;User_RxIndication&gt;</code> synchron <code>Copy Data()</code> gegen den Treiber (<code>Can</code>) auf.\n</li><li>Ohne temporären Puffer erfolgt <code>Copy Data()</code> direkt gegen den Hardware-Controller (<code>CanController</code>).\n</li></ul>\n</li><li>Nach Rückkehr aus <code>&lt;User_RxIndication&gt;()</code> kehrt auch <code>CanIf_RxIndication()</code> zum <code>Can</code>-Treiber zurück.\n</li><li>Der Treiber revalidiert das Hardware-Objekt im Controller über <code>Validation of hardware object()</code>.\n</li><li>Die Interrupt-Service-Routine schließt mit dem Rücksprung aus <code>Receive Interrupt()</code> ab.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Synchroner Indikationspfad: Die gesamte Weiterleitung bis in den <code>CanIf User</code> und das Kopieren der Nutzdaten erfolgen im Kontext der Interrupt-Service-Routine (ISR) des CAN-Controllers.\n</li><li>Datenkonsistenz: Das Hardware-Objekt bleibt während des gesamten Kopiervorgangs gesperrt (invalidiert), um ein Überschreiben durch nachfolgende Telegramme zu verhindern.\n</li><li>Normalisierung vs. Direkthandling: Der Treiber unterstützt wahlweise temporäre Pufferung zur Normalisierung controllerspezifischer Speicherlayouts oder den direkten Zugriff auf Peripherieregister.\n</li><li>Optionale Prüfungen: Software-Filterung und Data Length Check sind konfigurierbar.\n</li><li>Hinweis zur Schnittstellenparametrisierung: Parameter der User-Indikation variieren bei abweichenden Usern (exemplarisch erwähnt für CanTp).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-fb77ed0e788ddb33", "to": "FIG-378b98780b692dce", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-378b98780b692dce", "to": "FIG-73705e281667570f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Kommentarfeld links: Begriff „DLC check“ durch „Data Length Check“ ersetzt („Data Length Check and software filtering are only performed, if enabled (configuration)“).\n</li><li>Verzweigung/Guard im CanIf-Ablauf: Bedingungsbeschriftung „[CAN L-PDU ID was found]:DLC Check (optional)“ durch „[CAN L-PDU ID was found]: Data Length Check (optional)“ ersetzt.\n</li></ul>"}, {"from": "FIG-73705e281667570f", "to": "FIG-f7ea097f846ddc03", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f7ea097f846ddc03", "to": "FIG-452fe907a1e23233", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-452fe907a1e23233", "to": "FIG-3e4c75f2a398480c", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Empfänger-Komponente: Oberer Kommunikationspartner von „CanIf User“ zu «module» <code>LSduR</code> geändert.\n</li><li>Indikations-Aufruf: Funktionsaufruf <code>&lt;User_RxIndication&gt;(PduIdType, const PduInfoType*)</code> und Rückkehr <code>&lt;User_RxIndication&gt;()</code> durch <code>LSduR_CanIfRxIndication(PduIdType, const PduInfoType*)</code> bzw. <code>LSduR_CanIfRxIndication()</code> ersetzt.\n</li><li>Kommentarfeld rechts: Hinweiskasten „Exemplary call: parameters differ for User=CanTp“ entfernt.\n</li></ul>"}, {"from": "FIG-3e4c75f2a398480c", "to": "FIG-6b204f1857b902e8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
